/**
 * Each chat model's reasoning levels, and whether it takes a token budget,
 * for `chat({ reasoning })`. A model that is not here does not reason.
 */
export type VercelGatewayModelReasoningByName = {
  [K in keyof typeof VERCEL_GATEWAY_REASONING]: ModelReasoningCapability<
    (typeof VERCEL_GATEWAY_REASONING)[K]
  >
}

/**
 * Runtime map from chat model id to its reasoning data, for the text
 * adapters. An unknown id gives `undefined`: the adapter sends no reasoning
 * field.
 */
export const VERCEL_GATEWAY_MODEL_REASONING: Readonly<
  Record<string, ModelReasoning>
> = VERCEL_GATEWAY_REASONING
